/* CEC 初始化第一步：先 DeInit，确保时钟与寄存器都是干净状态 */
CEC_DeInit();

/* 第二步才开 CEC 时钟 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_CEC, ENABLE);

CEC_InitTypeDef CEC_InitStructure;

CEC_DeInit();
RCC_APB1PeriphClockCmd(RCC_APB1Periph_CEC, ENABLE);

/* 注意：这里还必须在 RCC 侧把 CEC 时钟源配好（HSE/1.5 或内部源） */

CEC_InitStructure.CEC_BitTimingMode = CEC_BitTimingStdMode;
CEC_InitStructure.CEC_BitPeriodMode = CEC_BitPeriodStdMode;
CEC_Init(&CEC_InitStructure);

CEC_Cmd(ENABLE);

NVIC_InitTypeDef NVIC_InitStructure;

CEC_ITConfig(ENABLE);                       /* 开 CEC 中断总开关 */

NVIC_InitStructure.NVIC_IRQChannel = CEC_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 2;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

void CEC_IRQHandler(void)
{
  if (CEC_GetITStatus(CEC_IT_RBTF) != RESET)
  {
    uint8_t b = CEC_ReceiveDataByte();
    CEC_ClearITPendingBit(CEC_IT_RBTF);
  }
}

/* 把本机配置成「播放设备」，逻辑地址 4 */
CEC_OwnAddressConfig(4);
CEC_Cmd(ENABLE);

/* CEC 时钟源与目标位时序决定预分频值，务必按参考手册的公式计算 */
/* 例：CEC 时钟 = HSE/1.5 = 8MHz/1.5 ≈ 5.33MHz */
CEC_SetPrescaler(0x0000);   /* 占位：请按手册算出真实值再填 */

CEC_Cmd(ENABLE);

/* 发送一个完整 CEC 报文：头块 + 2 个数据块 */
CEC_StartOfMessage();

CEC_SendDataByte(0x40);                      /* 头块：本机地址 4 → 目标 0(TV) */
while (CEC_GetFlagStatus(CEC_FLAG_TBTFE) == RESET);  /* 等发送寄存器空 */
CEC_ClearFlag(CEC_FLAG_TBTRF);

CEC_EndOfMessageCmd(DISABLE);
CEC_SendDataByte(0x0D);                      /* 数据块：例如「图像查看开」 */
while (CEC_GetFlagStatus(CEC_FLAG_TBTFE) == RESET);
CEC_ClearFlag(CEC_FLAG_TBTRF);

CEC_EndOfMessageCmd(ENABLE);                 /* 最后一字节带 EOM */
CEC_SendDataByte(0x00);
while (CEC_GetFlagStatus(CEC_FLAG_TBTFE) == RESET);
CEC_ClearFlag(CEC_FLAG_TBTRF);

uint8_t rx[16];
uint8_t n = 0;

/* 轮询接收一帧 */
while (CEC_GetFlagStatus(CEC_FLAG_REOM) == RESET)   /* 未收到报文结束 */
{
  if (CEC_GetFlagStatus(CEC_FLAG_RBTF) != RESET)
  {
    rx[n++] = CEC_ReceiveDataByte();   /* 先读 */
    CEC_ClearFlag(CEC_FLAG_RBTF);      /* 再清标志 */
  }

  if (CEC_GetFlagStatus(CEC_FLAG_RERR) != RESET)
  {
    CEC_ClearFlag(CEC_FLAG_RERR);
    n = 0;                             /* 接收错误，整帧作废 */
  }
}

/* 每次新报文都以 StartOfMessage 开头 */
CEC_StartOfMessage();
CEC_SendDataByte(0x40);   /* 头块 */
/* ... 后续数据块 ... */
CEC_EndOfMessageCmd(ENABLE);
CEC_SendDataByte(0x00);

CEC_StartOfMessage();                 /* 起始位 */
CEC_SendDataByte(0x40);              /* 头块：自身地址 + 目标地址 */
CEC_EndOfMessageCmd(DISABLE);
CEC_SendDataByte(0x0D);              /* 数据块 1 */

CEC_EndOfMessageCmd(ENABLE);         /* 最后一个字节，置 EOM */
CEC_SendDataByte(0x00);              /* 数据块 2（末块） */

/* 等发送完成标志 */
while (CEC_GetFlagStatus(CEC_FLAG_TBTRF) == RESET);

/* 发送一帧后检查是否被应答 */
while (CEC_GetFlagStatus(CEC_FLAG_TBTFE) == RESET);
CEC_ClearFlag(CEC_FLAG_TBTRF);
CEC_ClearFlag(CEC_FLAG_TERR);

if (CEC_GetFlagStatus(CEC_FLAG_ACKE) != RESET)
{
  /* 末字节没被应答：地址不对，或总线上没有这个设备 */
  CEC_ClearFlag(CEC_FLAG_ACKE);
}

/* 接收完一个字节：先读数据，再清标志 */
if (CEC_GetFlagStatus(CEC_FLAG_RBTF) != RESET)
{
  rx[n++] = CEC_ReceiveDataByte();
  CEC_ClearFlag(CEC_FLAG_RBTF);
}

/* 一次清掉全部错误标志，准备下一次通信 */
CEC_ClearFlag(CEC_FLAG_TERR | CEC_FLAG_RERR | CEC_FLAG_BTE | CEC_FLAG_BPE | CEC_FLAG_ACKE);

void CEC_IRQHandler(void)
{
  if (CEC_GetITStatus(CEC_IT_RBTF) != RESET)
  {
    /* 收到一个数据块 */
    rx_buf[rx_len++] = CEC_ReceiveDataByte();
    CEC_ClearITPendingBit(CEC_IT_RBTF);
  }

  if (CEC_GetITStatus(CEC_IT_RERR) != RESET)
  {
    /* 接收错误：丢弃本帧重新同步 */
    rx_len = 0;
    CEC_ClearITPendingBit(CEC_IT_RERR);
  }
}

void CEC_IRQHandler(void)
{
  if (CEC_GetITStatus(CEC_IT_RBTF) != RESET)
  {
    rx_buf[rx_len++] = CEC_ReceiveDataByte();
    CEC_ClearITPendingBit(CEC_IT_RBTF);
  }

  /* 一次性清掉两个错误挂起位 */
  CEC_ClearITPendingBit(CEC_IT_RERR | CEC_IT_TERR);
}
